export const LCCP_CREST_BASE64 = "";
export const LCCP_BANNER_BASE64 = "";

export function base64ToUint8Array(base64: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return Buffer.from(base64, "base64");
  }
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export function getLccpCrestBuffer(): Uint8Array {
  return base64ToUint8Array(LCCP_CREST_BASE64);
}

export function getLccpBannerBuffer(): Uint8Array {
  return base64ToUint8Array(LCCP_BANNER_BASE64);
}
